example_item.example_item_data:
t = nelson.io.tar.open([], 'w', 'Compression', 'gzip');
nelson.io.tar.write(t, 'notes/hello.txt', 'Hello tar');
nelson.io.tar.write(t, 'data.bin', uint8(1:100));
bytes = nelson.io.tar.tobytes(t);
r = nelson.io.tar.open(bytes);
r.Compression
nelson.io.tar.entries(r)
nelson.io.tar.readtext(r, 'notes/hello.txt')
nelson.io.tar.close(r);

folder = tempname();
mkdir(fullfile(folder, 'data'));
filewrite(fullfile(folder, 'data', 'a.txt'), 'first file');
filewrite(fullfile(folder, 'data', 'b.txt'), 'second file');
filename = fullfile(folder, 'data.tar.gz');
t = nelson.io.tar.open(filename, 'w');
names = nelson.io.tar.add(t, fullfile(folder, 'data'))
nelson.io.tar.close(t);
r = nelson.io.tar.open(filename);
filenames = nelson.io.tar.extract(r, fullfile(folder, 'out'))
nelson.io.tar.close(r);
rmdir(folder, 's');

t = nelson.io.tar.open([], 'w');
fid = nelson.io.tar.fopen(t, 'table.csv', 'w');
fprintf(fid, '%d,%g\n', [1:3; (1:3) / 10]);
fclose(fid);
r = nelson.io.tar.open(nelson.io.tar.tobytes(t));
fid = nelson.io.tar.fopen(r, 'table.csv');
C = textscan(fid, '%d,%f')
fclose(fid);
nelson.io.tar.close(r);
nelson.io.tar.compressions()
